const body = $json.body || $json;

console.log('Received payload:', JSON.stringify(body, null, 2));

// Try multiple paths to extract data
const record = body.record || body;

// Phone - prioritize customer_phone field
let phone = record.customer_phone || record.phone || body.customer_phone || '';

// Name  
let name = record.customer_name || record.name || body.customer_name || 'Cliente';

// Service - try multiple paths
let service = record.service_name || record.service?.name || body.service_name || body.service?.name;
if (!service && record.service_id) {
  service = 'Servicio reservado';
}
service = service || 'Servicio';

// Professional
let professional = record.professional_name || record.professional?.name || body.professional_name || body.professional?.name || 'Profesional';

// Datetime
let datetime = record.start_time || record.datetime || body.start_time || '';

// Shop sender
let shop_sender = record.shop?.phone || body.shop_number_sender || body.verified_sender_number || '5493586548065';

if (!phone) {
  console.log('No phone found, skipping notification');
  return [];
}

return {
  json: {
    phone,
    name,
    service,
    professional,
    datetime,
    shop_sender
  }
};

let phone = $json.phone;
let shop_sender = $json.shop_sender;
let name = $json.name;
let service = $json.service;
let professional = $json.professional;
let datetime = $json.datetime;

if (!phone) return [];

// Clean phone
const cleaningRegex = /[^\d]/g;
let cleanPhone = phone.toString().replace(cleaningRegex, '');
if (cleanPhone.startsWith('0')) cleanPhone = cleanPhone.substring(1);
if (!cleanPhone.startsWith('54')) cleanPhone = '54' + cleanPhone;

// Clean sender
let cleanSender = '5493586548065';
if (shop_sender) {
  let tempSender = shop_sender.toString().replace(cleaningRegex, '');
  if (tempSender.length > 5) cleanSender = tempSender;
}

// Format date
let formattedDate = '';
let formattedTime = '';
if (datetime) {
  const separator = datetime.includes('T') ? 'T' : ' ';
  const [datePart, timePart] = datetime.split(separator);
  if (datePart) {
    const [year, month, day] = datePart.split('-');
    formattedDate = `${day}/${month}/${year}`;
  }
  if (timePart) {
    formattedTime = timePart.substring(0, 5);
  }
}

return {
  json: {
    sender: cleanSender,
    recipient: cleanPhone,
    p1_name: name || 'Cliente',
    p2_date: formattedDate,
    p3_time: formattedTime,
    p4_service: service || 'Servicio',
    p5_prof: professional || 'Profesional'
  }
};
